WITH filtered AS (SELECT *, COALESCE(amount, 0) AS amount_filled, DATEDIFF(CURRENT_DATE(), paid_at) AS days_since_paid_at FROM payments WHERE paid_at > TIMESTAMP '2023-07-21 17:00:00') SELECT id, amount, status, days_since_paid_at, COUNT(amount) OVER (PARTITION BY method ORDER BY CAST(paid_at AS BIGINT) RANGE BETWEEN 2592000 PRECEDING AND CURRENT ROW) AS amount_count_30d, MAX(amount_filled) OVER (PARTITION BY status, order_id ORDER BY CAST(paid_at AS BIGINT) RANGE BETWEEN 604800 PRECEDING AND CURRENT ROW) AS amount_filled_max_7d, NTILE(4) OVER (ORDER BY days_since_paid_at, id) AS days_since_paid_at_bucket FROM filtered;
